function getProductImgCheckout(productMasterID) {

  let modifiedMasterID = productMasterID.slice(0, -5) + '_' + productMasterID.slice(-5);

  let images = document.querySelectorAll('img.js-producttile_image.b-product_image');
  
  if (images.length === 0) {
	return '';
  }

  for (let img of images) {
    let imgUrl = img.getAttribute('src');

    if (imgUrl.includes(modifiedMasterID)) {
      let finalUrl = 'https://www.dolcegabbana.com' + imgUrl.split('.jpg')[0] + '.jpg';
      return finalUrl;
    }
  }

  return '';
}

