function getCategoryIdFromBreadcrumb(o){
	try {
		let s = [...o];
		if (s.length > 1) s.shift(); // Strip "fashion"
		if (s.length === 1) return s[0].toLowerCase();
		let r = [];
		s.forEach((e, i) => {
			if (!(s[i+1] && s[i+1].indexOf(e) !== -1)) r.push(e);
		});
		if (r.length === 1) return r[0].replaceAll("-", "|").toLowerCase();
		else return r.join("|").toLowerCase();
	} catch(e) {
		consoleDebug('getCategoryId - ex: ' + e);
		return '';
	}
}

function getCustomCategoryIdFromBreadcrumb(o){ /* ===== Aggiunto check per parent category ===== */
	try {
		let s = [...o];
		if (s.length > 1) s.shift(); // Strip "fashion"
		if (s.length === 1) return s[0].toLowerCase();
		let r = [];
		/*let arr_length = s.length-2;
		r.push(s[arr_length]);*/
		s.forEach((e, i) => {
			if (!(s[i+1] && s[i+1].indexOf(e) !== -1)) r.push(e);
		});
		if (r.length === 1) return r[0].replaceAll("|", "-").toLowerCase();
		else return r.join("-").toLowerCase();
	} catch(e) {
		consoleDebug('getCustomCategoryId - ex: ' + e);
		return '';
	}
}

function getGeneralId(s){
    try {
        var temp = s.replace(/[,\.&%<>']/g, '');
        temp = temp.trim();
        temp = temp.replace(/ /g, '_');
        temp = temp.replace(/__/g, '_');
        return temp.toLowerCase();
    } catch(e) {
        consoleDebug('getGeneralId - ex: ' + e);
      
        return '';
    }
}

function getFurnitureLanguage() {
    try {
        let lang = Evergage.cashDom('html').attr('lang');
        return lang.split('-')[0].toLowerCase();
    } catch(e) {
        consoleDebug('getFurnitureLanguage - ex: ' + e);

        return 'en';
    }
}

function getFurnitureCountry() {
    try {
        var country = CURRENT_COUNTRY;

        if (!country && country !== "UNDEFINED"){
            return 'GB';
        }

        return country.toUpperCase();

    } catch(e) {
        consoleDebug('getFurnitureCountry - ex: ' + e);

        return 'GB';
    }
}

function getFurnitureLocale() {
    try {
        let lang = getFurnitureLanguage();
        let country = getFurnitureCountry();

        return lang.toLowerCase() + '_' + country.toUpperCase();
    } catch(e) {
        consoleDebug('getFurnitureLocale - ex: ' + e);

        return '';
    }
}

function getCategoryNameFromBreadcrumb(s){
    try {
        var temp = s.replace(/>/g, ' / ');
        var temp = temp.replace('Fashion / ', '');
        return temp;
    } catch(e) {
        consoleDebug('getCategoryNameFromBreadcrumb - ex: ' + e);

        return '';
    }
}

function getCustomCategoryPath() {
    try {
        consoleDebug("getCustomCategoryPath - init");

        let categoryPath = [];
        
        if(getProductObj()?.URI !== window.location.pathname)
            return [];
            
        if(getProductObj()?.userInfo?.language === 'en')						
            categoryPath.push(Evergage.util.getValueFromNestedObject("productCategoryPathGPF", getProductObj()).replace(/>/g, '/'));
        
        
        consoleDebug('getCustomCategoryPath - is: ' + categoryPath);

        return categoryPath;
    } catch (e) {
        consoleDebug('getCustomCategoryPath - ex: ' + e);
        return [];
    }
}

  
